CREATE TABLE integrations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID REFERENCES organizations(id) ON DELETE CASCADE, provider TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('disconnected','pending','connected','error','quota_exceeded')) DEFAULT 'disconnected', external_account_id TEXT, scopes TEXT[] NOT NULL DEFAULT '{}', encrypted_access_token BYTEA, encrypted_refresh_token BYTEA, token_expires_at TIMESTAMPTZ, last_error TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(organization_id,provider));
CREATE TABLE integration_oauth_states (state_hash TEXT PRIMARY KEY, provider TEXT NOT NULL, organization_id UUID REFERENCES organizations(id) ON DELETE CASCADE, redirect_uri TEXT NOT NULL, expires_at TIMESTAMPTZ NOT NULL, used_at TIMESTAMPTZ);
